(function(){
  'use strict';
  function hexToBytes(s){
    var t=String(s||'').replace(/0x/gi,' ').replace(/[^0-9a-fA-F]/g,'');
    if(t.length%2) t=t.slice(0,-1);
    var o=new Uint8Array(t.length/2);
    for(var i=0;i<o.length;i++) o[i]=parseInt(t.substr(i*2,2),16);
    return o;
  }
  function b64ToBytes(s){
    var t=String(s||'').replace(/[^A-Za-z0-9+/=]/g,'');
    var A='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
    var out=[],buf=0,bits=0;
    for(var i=0;i<t.length;i++){
      if(t[i]==='=') break;
      var v=A.indexOf(t[i]); if(v<0) continue;
      buf=(buf<<6)|v; bits+=6;
      if(bits>=8){ bits-=8; out.push((buf>>bits)&255); }
    }
    return new Uint8Array(out);
  }
  function toHex(b){ var o=[]; for(var i=0;i<b.length;i++){var x=b[i].toString(16); o.push(x.length<2?'0'+x:x);} return o.join(''); }
  function appleDate(secs){
    var ms = Date.UTC(2001,0,1) + secs*1000;
    var d = new Date(ms);
    return isNaN(d.getTime()) ? ('date '+secs) : d.toISOString().replace('.000','');
  }
  function readUInt(b,p,n){ var v=0; for(var i=0;i<n;i++) v=v*256+b[p+i]; return v; }
  function readSInt(b,p,n){
    if(n<=6){ var v=readUInt(b,p,n); if(b[p]&128) v-=Math.pow(2,n*8); return v; }
    // 8/16 字节整数：bplist 中 8 字节整数为有符号
    var hi=readUInt(b,p,4), lo=readUInt(b,p+4,4);
    if(n===8 && (b[p]&128)) return hi*4294967296+lo - Math.pow(2,64);
    return hi*4294967296+lo;
  }
  function readReal(b,p,n){
    var dv=new DataView(b.buffer, b.byteOffset+p, n);
    return n===4 ? dv.getFloat32(0,false) : dv.getFloat64(0,false);
  }
  function utf16be(b,p,len){
    var s='';
    for(var i=0;i<len;i++) s+=String.fromCharCode((b[p+i*2]<<8)|b[p+i*2+1]);
    return s;
  }
  function ascii(b,p,len){ var s=''; for(var i=0;i<len;i++) s+=String.fromCharCode(b[p+i]); return s; }

  /* ---------------- 二进制 plist ---------------- */
  function parseBinary(b){
    var warns=[];
    if(b.length<40) throw new Error('文件过短（'+b.length+' 字节），不足魔数 + 32 字节尾部');
    var magic = ascii(b,0,8);
    if(magic.slice(0,6)!=='bplist') throw new Error('缺少 bplist 魔数（当前 "'+magic.slice(0,6)+'"）');
    var ver = magic.slice(6,8);
    if(ver!=='00') warns.push('版本 '+ver+' 非 00，字段布局可能不同');

    var tp = b.length-32;
    var offsetIntSize = b[tp+6], objectRefSize = b[tp+7];
    var numObjects = readUInt(b,tp+8,8);
    var topObject  = readUInt(b,tp+16,8);
    var tableOff   = readUInt(b,tp+24,8);
    if(!offsetIntSize || offsetIntSize>8) throw new Error('offsetIntSize='+offsetIntSize+' 非法');
    if(!objectRefSize || objectRefSize>8) throw new Error('objectRefSize='+objectRefSize+' 非法');
    if(tableOff + numObjects*offsetIntSize > b.length) throw new Error('偏移表越界（表位于 '+tableOff+'，共 '+numObjects+' 项）');
    if(topObject >= numObjects) throw new Error('topObject='+topObject+' 超出对象数 '+numObjects);

    var offsets=[];
    for(var i=0;i<numObjects;i++) offsets.push(readUInt(b, tableOff+i*offsetIntSize, offsetIntSize));

    var seen = {};
    function obj(idx, depth){
      if(depth>64) throw new Error('嵌套超过 64 层，疑似循环引用');
      if(idx>=numObjects) throw new Error('对象引用 #'+idx+' 越界');
      var p = offsets[idx];
      if(p>=b.length) throw new Error('对象 #'+idx+' 偏移 '+p+' 越界');
      var m = b[p], hi = m>>4, lo = m&15, q = p+1;
      function count(){
        if(lo!==15) return lo;
        var mk=b[q++]; if((mk>>4)!==1) throw new Error('对象 #'+idx+' 的扩展长度标记非法');
        var n=Math.pow(2, mk&15), c=readUInt(b,q,n); q+=n; return c;
      }
      if(m===0x00) return {type:'null', value:null};
      if(m===0x08) return {type:'bool', value:false};
      if(m===0x09) return {type:'bool', value:true};
      if(m===0x0F) return {type:'fill', value:null};
      if(hi===1){ var n1=Math.pow(2,lo); return {type:'int', value:readSInt(b,q,n1)}; }
      if(hi===2){ var n2=Math.pow(2,lo); return {type:'real', value:readReal(b,q,n2)}; }
      if(hi===3){ var s=readReal(b,q,8); return {type:'date', value:appleDate(s), raw:s}; }
      if(hi===4){ var c4=count(); return {type:'data', value:toHex(b.subarray(q,q+c4)), bytes:c4}; }
      if(hi===5){ var c5=count(); return {type:'string', value:ascii(b,q,c5)}; }
      if(hi===6){ var c6=count(); return {type:'string', value:utf16be(b,q,c6), utf16:true}; }
      if(hi===8){ return {type:'uid', value:readUInt(b,q,lo+1)}; }
      if(hi===10 || hi===12){
        var ca=count(), arr=[];
        for(var a=0;a<ca;a++){ arr.push(obj(readUInt(b,q+a*objectRefSize,objectRefSize), depth+1)); }
        return {type: hi===10?'array':'set', value:arr};
      }
      if(hi===13){
        var cd=count(), ents=[], keyBase=q, valBase=q+cd*objectRefSize, prev=null;
        for(var d=0;d<cd;d++){
          var kNode = obj(readUInt(b,keyBase+d*objectRefSize,objectRefSize), depth+1);
          var vNode = obj(readUInt(b,valBase+d*objectRefSize,objectRefSize), depth+1);
          var k = String(kNode.value);
          if(prev!==null && k<prev) warns.push('字典键未按升序排列："'+prev+'" 之后出现 "'+k+'"');
          prev=k;
          ents.push({key:k, value:vNode});
        }
        return {type:'dict', value:ents};
      }
      throw new Error('未知对象标记 0x'+m.toString(16)+'（对象 #'+idx+' @'+p+'）');
    }
    var root = obj(topObject, 0);
    return {format:'binary', version:ver, numObjects:numObjects, topObject:topObject,
            offsetIntSize:offsetIntSize, objectRefSize:objectRefSize, root:root, warnings:warns};
  }

  /* ---------------- XML plist ---------------- */
  function unent(s){
    return s.replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"')
            .replace(/&apos;/g,"'").replace(/&#(\d+);/g,function(_,d){return String.fromCharCode(+d);})
            .replace(/&amp;/g,'&');
  }
  function parseXml(text){
    var warns=[];
    var s = String(text).replace(/<\?xml[\s\S]*?\?>/g,'').replace(/<!DOCTYPE[\s\S]*?>/g,'')
                        .replace(/<!--[\s\S]*?-->/g,'');
    var re=/<(\/?)([A-Za-z0-9_:-]+)([^>]*?)(\/?)>|([^<]+)/g, m, stack=[], root=null, pendingKey=null, keyBuf=null;
    function attach(node){
      if(!stack.length){ if(root) warns.push('根节点之后出现多余元素'); root=node; return; }
      var top=stack[stack.length-1];
      if(top.type==='dict'){
        if(pendingKey===null){ warns.push('字典中出现无 <key> 的值：'+node.type); return; }
        top.value.push({key:pendingKey, value:node}); pendingKey=null;
      } else if(top.type==='array'){ top.value.push(node); }
      else warns.push('容器 '+top.type+' 不能包含子元素');
    }
    while((m=re.exec(s))!==null){
      if(m[5]!==undefined){
        var txt=m[5];
        if(keyBuf!==null) keyBuf+=txt;
        else if(stack.length && stack[stack.length-1].pending!==undefined) stack[stack.length-1].pending+=txt;
        continue;
      }
      var close=m[1]==='/', tag=m[2].toLowerCase(), self=m[4]==='/';
      if(tag==='plist') continue;
      if(!close && !self){
        if(tag==='key'){ keyBuf=''; continue; }
        if(tag==='dict'||tag==='array'){ var n={type:tag, value:[]}; attach(n); stack.push(n); continue; }
        stack.push({type:tag, pending:'', value:null, leaf:true}); continue;
      }
      if(self){
        if(tag==='true'||tag==='false'){ attach({type:'bool', value:tag==='true'}); continue; }
        if(tag==='dict'||tag==='array'){ attach({type:tag, value:[]}); continue; }
        attach({type:tag, value:null}); continue;
      }
      // 闭合
      if(tag==='key'){ pendingKey=unent(keyBuf||''); keyBuf=null; continue; }
      var top=stack.pop();
      if(!top){ warns.push('多余的闭合标签 </'+tag+'>'); continue; }
      if(top.type!==tag){ warns.push('标签不匹配：<'+top.type+'> 被 </'+tag+'> 闭合'); }
      if(top.leaf){
        var raw=(top.pending||'');
        var node;
        if(tag==='string') node={type:'string', value:unent(raw)};
        else if(tag==='integer') node={type:'int', value:parseInt(raw.trim(),10)};
        else if(tag==='real') node={type:'real', value:parseFloat(raw.trim())};
        else if(tag==='date') node={type:'date', value:raw.trim()};
        else if(tag==='data') node={type:'data', value:toHex(b64ToBytes(raw)), bytes:b64ToBytes(raw).length};
        else if(tag==='true'||tag==='false') node={type:'bool', value:tag==='true'};
        else { node={type:tag, value:unent(raw)}; warns.push('未知标签 <'+tag+'>'); }
        attach(node);
      }
    }
    if(!root) throw new Error('未找到根节点（需要 <dict>/<array>/标量）');
    if(stack.length) warns.push('有 '+stack.length+' 个标签未闭合');
    return {format:'xml', version:'1.0', root:root, warnings:warns, numObjects:null};
  }

  function parse(input){
    var raw = String(input||'').trim();
    if(!raw) return {value:null, error:'输入为空'};
    try{
      if(/^\s*</.test(raw)) return {value:parseXml(raw), error:''};
      var b;
      if(/^[0-9a-fA-F\s]+$/.test(raw)) b=hexToBytes(raw);
      else b=b64ToBytes(raw);
      if(b.length>=6 && ascii(b,0,6)==='bplist') return {value:parseBinary(b), error:''};
      if(b.length && b[0]===0x3C) return {value:parseXml(ascii(b,0,b.length)), error:''};
      return {value:null, error:'无法识别输入：既不是 XML plist，也没有 bplist 魔数'};
    }catch(e){ return {value:null, error:e.message}; }
  }

  function toJson(node){
    if(!node) return null;
    if(node.type==='dict'){ var o={}; for(var i=0;i<node.value.length;i++) o[node.value[i].key]=toJson(node.value[i].value); return o; }
    if(node.type==='array'||node.type==='set'){ var a=[]; for(var j=0;j<node.value.length;j++) a.push(toJson(node.value[j])); return a; }
    return node.value;
  }
  function countNodes(node){
    if(!node) return 0;
    var n=1;
    if(node.type==='dict'){ for(var i=0;i<node.value.length;i++) n+=countNodes(node.value[i].value); }
    else if(node.type==='array'||node.type==='set'){ for(var j=0;j<node.value.length;j++) n+=countNodes(node.value[j]); }
    return n;
  }
  function lines(node, key, depth, out){
    out=out||[]; depth=depth||0;
    var pad=new Array(depth+1).join('  ');
    var label = key!==null && key!==undefined ? key+': ' : '';
    if(node.type==='dict'){
      out.push(pad+label+'{ '+node.value.length+' 项 }');
      for(var i=0;i<node.value.length;i++) lines(node.value[i].value, node.value[i].key, depth+1, out);
    } else if(node.type==='array'||node.type==='set'){
      out.push(pad+label+'[ '+node.value.length+' 项 ]');
      for(var j=0;j<node.value.length;j++) lines(node.value[j], null, depth+1, out);
    } else {
      var v=node.value;
      if(node.type==='data') v='<'+node.bytes+' 字节: '+String(v).slice(0,32)+(String(v).length>32?'…':'')+'>';
      if(node.type==='string') v=JSON.stringify(v);
      out.push(pad+label+String(v)+'   ('+node.type+')');
    }
    return out;
  }

  var API={parse:parse, parseBinary:parseBinary, parseXml:parseXml, toJson:toJson,
           countNodes:countNodes, lines:lines, hexToBytes:hexToBytes, b64ToBytes:b64ToBytes,
           toHex:toHex, appleDate:appleDate};
  if(typeof module!=='undefined' && module.exports) module.exports=API;
  if(typeof window!=='undefined') window.__PlistForge__=API;
})();
